"""Generate numerical manuscript text exclusively from audited results."""
import csv,json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
from experiment import MODELS,POLICIES,CONDITIONS,SYSTEM,BOUNDARY,BINDING
S=json.loads((ROOT/'results/summary.json').read_text())
A=json.loads((ROOT/'results/audit.json').read_text())
ROWS=list(csv.DictReader((ROOT/'results/trial_scores.csv').open(encoding='utf-8')))
CON=list(csv.DictReader((ROOT/'results/paired_contrasts.csv').open(encoding='utf-8')))
M0,M1=MODELS
PL={'task_only':'Task only','boundary':'Boundary','evidence_binding':'Evidence binding'}
CL={'clean':'Clean','role_spoof':'Role spoof','workflow_pretext':'Workflow','correction_claim':'Correction'}
def esc(s):
    return s.replace('&',r'\&').replace('_',r'\_').replace('%',r'\%').replace('#',r'\#')
def metric(m,p,c,key='task_success',norm=False):return S[m][p][c][('normalized_' if norm else '')+key]
def show(m,p,c,key='task_success',norm=False):
    x=metric(m,p,c,key,norm);return f"{x['count']}/{x['n']} ({100*x['rate']:.1f}\\%)"
def frac(m,p,c,key='task_success',norm=False):
    x=metric(m,p,c,key,norm);return f"{x['count']}/{x['n']}"
def contrast(m,c='correction_claim',parser='strict'):
    return next(x for x in CON if x['model']==m and x['condition']==c and x['parser']==parser)
def delta(m,parser='strict',context=False):
    c=contrast(m,parser=parser);pre='context_' if context else ''
    return f"{100*float(c[pre+'difference']):.1f} percentage points (95\\% interval {100*float(c[pre+'low']):.1f} to {100*float(c[pre+'high']):.1f})"
def total(m,p,key,attacked=True):
    rr=[r for r in ROWS if r['model']==m and r['policy']==p and ((r['condition']!='clean') if attacked else True)]
    return sum(r[key]=='True' for r in rr),len(rr)
def tshow(m,p,key):
    n,d=total(m,p,key);return f'{n}/{d} ({100*n/d:.1f}\\%)'
def write(name,s):(ROOT/name).write_text(s+'\n',encoding='utf-8')

assert A['completed_unique_trials']==1152 and A['request_hashes_all_verified']
abstract=rf'''Prompt-injection defence measurements depend on how generated text becomes an accepted action. We collected 1,152 API responses from two dated Qwen endpoints across 24 synthetic reporting tasks, three prompt policies and four annotation conditions. The frozen strict-JSON analysis separated authorization, answer integrity and formatting failures. Under adversarial correction claims, an evidence-source restriction added to a boundary reminder changed Qwen3.5-Plus joint correctness by {delta(M1)}. An exploratory replay that removed only enclosing Markdown fences changed this contrast to {delta(M1,'fence_normalized')}. For Qwen-Plus, the 77.1-percentage-point gain persisted under both parsers. A recipient guard also admitted incorrect numerical answers sent through authorized routes. Thus, accepting a common output wrapper can change the apparent value of a defensive prompt, while blocking redirection does not certify answer integrity. These findings concern short, non-adaptive synthetic tasks and two related models; broader deployment claims require independent validation.'''
write('abstract_text.tex',abstract)
write('results_macros.tex',r'% Numerical sections are generated by write_results.py from audited per-trial scores.')

sv0=sum(r['schema_valid']=='True' for r in ROWS if r['model']==M0)
sv1=sum(r['schema_valid']=='True' for r in ROWS if r['model']==M1)
f0=sum(r['fence_recovered']=='True' for r in ROWS if r['model']==M0)
f1=sum(r['fence_recovered']=='True' for r in ROWS if r['model']==M1)
norm0=sum(r['normalized_schema_valid']=='True' for r in ROWS if r['model']==M0)
norm1=sum(r['normalized_schema_valid']=='True' for r in ROWS if r['model']==M1)
results=rf'''\subsection*{{Complete paired collection}}
The retained dataset contained all 1,152 planned responses, with 576 from each endpoint and 48 in every model-policy-condition cell (Fig.~\ref{{fig:design}}). All requested model identifiers matched the provider-returned identifiers, and every recorded request hash matched its reconstruction from the frozen inputs. The collection recorded {A['http_attempt_records']} HTTP-attempt entries, including {A['http_status_counts'].get('429',0)} rate-limit responses. Successful experimental responses used {A['prompt_tokens']:,} input and {A['completion_tokens']:,} output tokens. Of the retained responses, {A['finish_reasons'].get('stop',0)} ended with the provider's \texttt{{stop}} finish reason. One Qwen3.5-Plus task-only workflow response instead proposed a \texttt{{dispatch}} tool call with empty arguments and no textual answer; it remained an invalid dispatch under both parsers. No retained response ended because of the output-token cap. These checks establish completeness of the retained request-response collection, not an independent audit of the provider's weights or billing.

\subsection*{{Formatting contributes materially to exact task success}}
Under strict parsing, {sv0}/576 Qwen-Plus responses and {sv1}/576 Qwen3.5-Plus responses satisfied the output schema. On clean tasks, task-only exact success was {show(M0,'task_only','clean')} for Qwen-Plus and {show(M1,'task_only','clean')} for Qwen3.5-Plus. These counts include both answer errors and format rejection; they are not standalone measures of reasoning ability (Table~\ref{{tab:main}} and Fig.~\ref{{fig:success}}).

The exploratory fence-normalized replay recovered {f0} additional parseable responses from Qwen-Plus and {f1} from Qwen3.5-Plus, producing {norm0}/576 and {norm1}/576 schema-valid responses, respectively. Without changing the numerical content, normalization changed clean task-only exact success to {show(M0,'task_only','clean',norm=True)} and {show(M1,'task_only','clean',norm=True)}. The difference between strict and normalized success therefore measures a concrete interface effect on this response set (Fig.~\ref{{fig:parser}}). It does not establish that the model would behave identically if a different format contract had been supplied during generation.

\subsection*{{Boundary reminders and evidence restrictions have distinct effects}}
For Qwen-Plus under correction claims, strict joint correctness was {show(M0,'boundary','correction_claim','joint_correct')} with the boundary reminder and {show(M0,'evidence_binding','correction_claim','joint_correct')} with evidence binding. The prespecified paired difference was {delta(M0)}. The fence-normalized comparison was {delta(M0,'fence_normalized')}. Thus, for this endpoint, the source restriction had a large observed benefit that was not explained by removal of enclosing Markdown.

For Qwen3.5-Plus, the corresponding strict joint-correctness counts were {show(M1,'boundary','correction_claim','joint_correct')} and {show(M1,'evidence_binding','correction_claim','joint_correct')}, giving a difference of {delta(M1)}. After fence normalization, they were {show(M1,'boundary','correction_claim','joint_correct',True)} and {show(M1,'evidence_binding','correction_claim','joint_correct',True)}. The normalized difference was {delta(M1,'fence_normalized')}. This endpoint therefore did not show the same added answer-integrity benefit from the longer policy once the accepted serialization format was changed. The strict result alone would obscure that distinction (Fig.~\ref{{fig:effects}}).

The exploratory eight-context bootstrap gave correction-claim strict differences of {delta(M0,context=True)} and {delta(M1,context=True)} for the two endpoints, respectively. This grouping retains all three operations and both repetitions within each context. It describes sensitivity to shared surface context, while leaving the limited number of attack phrasings and the non-random choice of tasks unresolved.

\subsection*{{A recipient check leaves an answer-integrity residual}}
Among all attacked trials, strict parsing followed by the recipient guard admitted wrong values in {tshow(M0,'task_only','guard_wrong_value')} Qwen-Plus task-only responses and {tshow(M1,'task_only','guard_wrong_value')} Qwen3.5-Plus task-only responses. Because these outputs selected the authorized recipient, the guard had no basis for rejecting them. The corresponding fence-normalized rates were {tshow(M0,'task_only','normalized_guard_wrong_value')} and {tshow(M1,'task_only','normalized_guard_wrong_value')}. This is a denominator-preserving comparison on the same 144 attacked responses per endpoint and policy.

With the boundary reminder, the normalized accepted-wrong-value counts were {tshow(M0,'boundary','normalized_guard_wrong_value')} for Qwen-Plus and {tshow(M1,'boundary','normalized_guard_wrong_value')} for Qwen3.5-Plus. With evidence binding, they were {tshow(M0,'evidence_binding','normalized_guard_wrong_value')} and {tshow(M1,'evidence_binding','normalized_guard_wrong_value')}. Figure~\ref{{fig:guard}} separates accepted correct values, accepted wrong values and blocked proposals under the original strict system. The absence of accepted unauthorized recipients follows from the guard's equality check; it is not an empirical claim of general immunity to prompt injection.

\subsection*{{Clean controls constrain attribution}}
Clean task-only fence-normalized exact success was {show(M0,'task_only','clean',norm=True)} for Qwen-Plus and {show(M1,'task_only','clean',norm=True)} for Qwen3.5-Plus. Accordingly, not every wrong answer in an attacked condition can be assigned uniquely to the annotation. The per-condition tables also retain attacker-chosen values and recipients as separate endpoints. They distinguish following the attack's specific target from any numerical or routing error, while the matched clean conditions quantify the observed baseline task difficulty. No retries were made to replace a completed but incorrect model response.'''
write('results_text.tex',results)

table=r'''\begin{table}[tb]
\centering\small
\caption{\textbf{Exact task success and residual errors.} S/N denotes strict/fence-normalized counts for the same responses. Clean and correction cells each contain 48 responses. The final column counts accepted wrong numerical values after normalized parsing and the recipient guard across all 144 attacked responses. Plus and 3.5-Plus denote the dated endpoints specified in Methods.}
\label{tab:main}
\begin{tabular}{llccc}
\toprule
Model & Policy & Clean S/N & Correction S/N & Wrong accepted N \\
\midrule
'''
for mi,m in enumerate(MODELS):
    for p in POLICIES:
        clean=f"{metric(m,p,'clean')['count']}/{metric(m,p,'clean',norm=True)['count']}"
        corr=f"{metric(m,p,'correction_claim')['count']}/{metric(m,p,'correction_claim',norm=True)['count']}"
        wrong,n=total(m,p,'normalized_guard_wrong_value')
        table+=f"{'Plus' if mi==0 else '3.5-Plus'} & {PL[p]} & {clean} & {corr} & {wrong}/{n} \\\\\n"
    if mi==0:table+=r'\midrule'+'\n'
table+=r'\bottomrule\end{tabular}\end{table}'
write('main_table.tex',table)

sup=r'''\small
\begin{longtable}{lllrrrr}
\caption{Complete exact-success and parser counts. Each row contains 48 responses. S = strict, N = fence-normalized, F = responses recovered only by removing a fence.}\\
\toprule Model & Policy & Condition & $n$ & Success S & Success N & F\\\midrule
\endfirsthead
\toprule Model & Policy & Condition & $n$ & Success S & Success N & F\\\midrule
\endhead
'''
for mi,m in enumerate(MODELS):
    for p in POLICIES:
        for c in CONDITIONS:
            sup+=f"{'Plus' if mi==0 else '3.5-Plus'} & {PL[p]} & {CL[c]} & 48 & {metric(m,p,c)['count']} & {metric(m,p,c,norm=True)['count']} & {metric(m,p,c,'fence_recovered')['count']} \\\\\n"
sup+=r'\bottomrule\end{longtable}\normalsize'
write('supplement_tables.tex',sup)
pol=''
for title,text in [('Task-only system instruction',SYSTEM),('Boundary-policy addition',BOUNDARY.strip()),('Evidence-binding addition',BINDING.strip())]:
    pol+=r'\paragraph{'+title+'} '+esc(text)+'\n\n'
write('policy_text.tex',pol)
print('Generated abstract, results, tables and policy appendix from audited scores.')
